CREATE OR REPLACE FUNCTION FNC_GETSTATUSLIB_PRA(P_NUNOTA INT) RETURN VARCHAR2 AS
V_STATUS CHAR;
BEGIN
BEGIN
WITH CAB AS ((SELECT CAB.STATUSNOTA
FROM TGFCAB CAB
WHERE CAB.NUNOTA = P_NUNOTA
UNION ALL
SELECT 'B' AS STATUS
FROM DUAL
WHERE EXISTS (SELECT 1
FROM TSILIB LIB
WHERE LIB.NUCHAVE = P_NUNOTA
AND LIB.TABELA IN ('TGFCAB','TGFITE')
AND (LIB.VLRLIBERADO < LIB.VLRATUAL
OR LIB.DHLIB IS NULL
AND NVL(LIB.CODUSULIB,0) = 0)

)
)
)


SELECT MAX(STATUSNOTA)
INTO V_STATUS
FROM CAB;
EXCEPTION WHEN OTHERS THEN
V_STATUS := 'A';
END;

RETURN V_STATUS;

END FNC_GETSTATUSLIB_PRA;
/
